"""Safe, investigation-scoped storage and checksum helpers."""
import hashlib
from pathlib import Path
from app.storage import jobs

def investigation_dir(job_id: str) -> Path:
    # IDs are UUIDs generated by the API; resolve and enforce the data-root boundary.
    target = (jobs.DATA_ROOT / "raw" / "earthdata" / job_id).resolve()
    target.relative_to(jobs.DATA_ROOT.resolve())
    target.mkdir(parents=True, exist_ok=True)
    return target

def checksum(path: str | Path) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as source:
        for block in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()
